suppressPackageStartupMessages({library(readxl);library(dplyr);library(tidyr);library(ggplot2);library(patchwork);library(scales)})
source(file.path(dirname(sub("^--file=", "", commandArgs(FALSE)[grepl("^--file=", commandArgs(FALSE))][1])), "_common.R"))
dat<-read_excel(resolve_data_path(),sheet="Baseline_to_FirstFU")
make_plot<-function(var,title){x<-dat%>%transmute(Group=Baseline_Pain_Group_3L,Change=.data[[var]])%>%bind_rows(dat%>%transmute(Group="Overall",Change=.data[[var]]))%>%count(Group,Change,name="n")%>%complete(Group,Change=CHANGE_LEVELS,fill=list(n=0))%>%group_by(Group)%>%mutate(Total=sum(n),Percent=100*n/Total,Label=ifelse(Percent>0,sprintf("%.1f%%",Percent),""))%>%ungroup()%>%mutate(Change=factor(Change,levels=c("Increased","Maintained","Decreased")),Group=factor(Group,levels=c("Severe pain (VAS ≥7)","Moderate pain (VAS 4–6)","Mild pain (VAS 0–3)","Overall"),labels=c("Severe pain (VAS ≥7, n=11)","Moderate pain (VAS 4–6, n=54)","Mild pain (VAS 0–3, n=126)","Overall (n=191)")))
 ggplot(x,aes(Group,Percent,fill=Change))+geom_col(width=.65)+geom_text(aes(label=Label),position=position_stack(vjust=.5),size=3.5)+coord_flip()+scale_y_continuous(limits=c(0,100),breaks=seq(0,100,20),expand=c(0,0))+scale_fill_manual(values=c(Increased="#E85C50",Maintained="#F4C542",Decreased="#4CAF50"))+labs(title=title,x=NULL,y="Percentage (%)",fill="Direction of change")+theme_classic()+theme(legend.position="bottom",plot.title=element_text(hjust=.5,face="bold"))}
p1<-make_plot("VAS_Response_FirstFU","VAS change category by baseline pain group");p2<-make_plot("Pain_Burden_Response_FirstFU","Pain-burden change category by baseline pain group");panel<-(p1/p2)+plot_annotation(tag_levels="A")
ggsave(file.path(output_dir(),"Supplementary_Figure_S1.png"),panel,width=9,height=7.5,dpi=600);ggsave(file.path(output_dir(),"Supplementary_Figure_S1.tiff"),panel,width=9,height=7.5,dpi=600,compression="lzw")
